package io.knowledgebrain.planning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import org.springframework.mock.web.MockHttpServletRequest;import jakarta.servlet.http.Cookie;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class RecurrenceApiTest {
 RecurrenceStore store;SpaceAuthorizationClient auth;RecurrenceController api;UUID space,id,actor;
 String input="{\"title\":\"Series\",\"description\":\"Body\",\"startsLocal\":\"2028-01-01T09:00:00\",\"endsLocal\":\"2028-01-01T10:00:00\",\"timeZone\":\"UTC\",\"taskId\":null,\"frequency\":\"DAILY\",\"interval\":1,\"count\":2,\"startsOverlap\":\"REJECT\",\"endsOverlap\":\"REJECT\"}";
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();id=ids.next();actor=ids.next();store=mock(RecurrenceStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyString(),eq("PRIVATE"),anyString())).thenReturn(actor);api=new RecurrenceController(store,auth,new SimpleMeterRegistry(),"https://localhost:8443");}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/recurrences");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void previewIsFreshReadOnlyAuthorityAndSameOrigin()throws Exception{for(int n=0;n<2;n++)assertEquals("no-store",api.preview(space.toString(),r("POST",input)).getHeaders().getCacheControl());verify(auth,times(2)).authorize(eq(space),any(),eq("SCHEDULE_READ"),eq("PRIVATE"),anyString());var cross=r("POST",input);cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.preview(space.toString(),cross)).getStatusCode().value());}
 @Test void strictPreviewInputRejectsDuplicatesUnknownPropertiesAndIntegerOverflow()throws Exception{for(String bad:List.of(input+" {}",input.replace("\"count\":2","\"count\":2,\"count\":3"),input.replace("\"count\":2","\"count\":4294967298"),input.replace("\"count\":2","\"count\":2.0"),input.replace("\"frequency\":\"DAILY\"","\"frequency\":\"MONTHLY\""),input.substring(0,input.length()-1)+",\"actorId\":null}"))assertThrows(ResponseStatusException.class,()->api.preview(space.toString(),r("POST",bad)));verifyNoInteractions(store);}
 @Test void cancellationRequiresIndependentStrongVersionAndExactConfirmation()throws Exception{String body="{\"fromOrdinal\":1,\"cancellationHash\":\""+"a".repeat(64)+"\"}";assertEquals(428,assertThrows(ResponseStatusException.class,()->api.cancel(space.toString(),id.toString(),r("POST",body))).getStatusCode().value());for(String tag:List.of("\"sc1\"","\"rc01\"","W/\"rc1\"","*")){var request=r("POST",body);request.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.cancel(space.toString(),id.toString(),request));}var request=r("POST",body);request.addHeader("If-Match","\"rc1\"");when(store.cancel(eq(space),eq(id),eq(actor),eq(1L),eq(1),eq("a".repeat(64)),anyString())).thenReturn(new RecurrenceStore.Series(id,space,"PRIVATE","RETIRED",2,null,"b".repeat(64),List.of(),1,"a".repeat(64),Instant.now().toString(),Instant.now().toString()));api.cancel(space.toString(),id.toString(),request);verify(store).cancel(eq(space),eq(id),eq(actor),eq(1L),eq(1),eq("a".repeat(64)),anyString());}
 @Test void everyHistoryAndCatalogReadUsesCurrentPrivateAuthority(){when(store.list(eq(space),anyString(),any(),anyInt())).thenReturn(new RecurrenceStore.Page(space,"ACTIVE",List.of(),null));api.list(space.toString(),r("GET",null));api.history(space.toString(),id.toString(),r("GET",null));verify(auth,times(2)).authorize(eq(space),any(),eq("SCHEDULE_READ"),eq("PRIVATE"),anyString());var extra=r("GET",null);extra.addParameter("space","foreign");assertThrows(ResponseStatusException.class,()->api.list(space.toString(),extra));}
}
